def extrair_campos(resposta):
    dados = resposta.get('dados', {})
    nome = dados.get('nome', 'desconhecido')
    cidade = dados.get('cidade', 'desconhecida')
    status = dados.get('status', 'indefinido')
    return {
        'nome': nome,
        'cidade': cidade,
        'status': status,
    }
